/// The current app's stroke icons: name to SVG paths on a 24-point grid, drawn by Icon.swift.
enum Icons {
    static let paths: [String: [String]] = parse([data1, data2])

    /// Each icon is its name, then one path per line, then a blank line.
    private static func parse(_ chunks: [String]) -> [String: [String]] {
        var icons: [String: [String]] = [:]
        for block in chunks.joined(separator: "\n").components(separatedBy: "\n\n") {
            let lines = block.split(separator: "\n").map(String.init)
            if let name = lines.first {
                icons[name] = Array(lines.dropFirst())
            }
        }
        return icons
    }
}
